 async function submit(event:React.FormEvent){event.preventDefault();setBusy('create');setError(undefined);try{const invitation=await api.createInvitation({email,role,scope});setCreated({email:invitation.email,acceptUrl:invitation.acceptUrl});setCreating(false);setEmail('');setRole('viewer');setScope('workspace');await q.refresh()}catch(value){setError(value)}finally{setBusy('')}}
